   837  static const u_int8_t ndpi_domain_level_automat[4][4]= {
   838    /* symbol,'.','-',inc */
   839    { 2,1,2,0 }, // start state
   840    { 2,0,0,0 }, // first char is '.'; disable .. or .-
   841    { 2,3,2,0 }, // part of domain name
   842    { 2,0,0,1 }  // next level domain name; disable .. or .-
   843  };
   844
   845  /*
   846   * domain level
   847   *  a. = 1
   848   * .a. = 1
   849   * a.b = 2
   850   */
   851
   852  static u_int8_t ndpi_domain_level(const char *name) {
   853    u_int8_t level = 1, state = 0;
   854    char c;
   855    while((c = *name++) != '\0') {
   856      c = c == '-' ? 2 : (c == '.' ? 1:0);
   857      level += ndpi_domain_level_automat[state][3];
   858      state  = ndpi_domain_level_automat[state][(u_int8_t)c];
   859      if(!state) break;
   860    }
   861    return state >= 2 ? level:0;
   862  }
