  6063    int len, num = 0;
  6064
  6065    if(!ndpi_str || !fd)
  6066      return(-1);
  6067
  6068    while(1) {
  6069      line = fgets(buffer, sizeof(buffer), fd);
  6070
  6071      if(line == NULL)
  6072        break;
  6073
  6074      len = strlen(line);
  6075
  6076      if((len <= 1) || (line[0] == '#'))
  6077        continue;
  6078
  6079      line[len - 1] = '\0';
  6080
  6081      if(ndpi_load_risky_domain(ndpi_str, line) >= 0)
